'use strict';
const fs = require('fs');
function resolveModule(baseDir, request) {
  for (const ext of ['', '.js', '.cjs', '.json']) {
    const candidate = baseDir + '/' + request + ext;
    if (fs.existsSync(candidate)) return candidate;
  }
  return null;
}
module.exports = { resolveModule };

