'use strict';
function findCycle(graph) {
  const stack = new Set();
  const seen = new Set();
  function dfs(node, trail) {
    if (stack.has(node)) return trail.concat(node);
    if (seen.has(node)) return null;
    seen.add(node); stack.add(node);
    for (const next of graph[node] || []) {
      const hit = dfs(next, trail.concat(node));
      if (hit) return hit;
    }
    stack.delete(node);
    return null;
  }
  for (const n of Object.keys(graph)) {
    const c = dfs(n, []);
    if (c) return c;
  }
  return null;
}
module.exports = { findCycle };

'use strict';
function matchesShape(value, shape) {
  if (value === null || typeof value !== 'object') return false;
  return Object.keys(shape).every((key) => typeof value[key] === shape[key]);
}
module.exports = { matchesShape };

'use strict';
function planFanout(workerCount, requests) {
  const buckets = Array.from({ length: workerCount }, () => []);
  requests.forEach((req, idx) => {
    buckets[idx % workerCount].push(req);
  });
  return buckets;
}
function quorumThreshold(total) {
  return Math.floor(total / 2) + 1;
}
module.exports = { planFanout, quorumThreshold };

'use strict';
function createSemaphore(limit) {
  let active = 0;
  return {
    tryAcquire() {
      if (active >= limit) return false;
      active += 1;
      return true;
    },
    release() { if (active > 0) active -= 1; },
    inUse() { return active; },
  };
}
module.exports = { createSemaphore };

