'use strict';
function detectCycle(history) {
  for (let len = 1; len <= history.length / 2; len += 1) {
    const tail = history.slice(-len);
    const prev = history.slice(-2 * len, -len);
    if (tail.length === prev.length && tail.every((v, i) => v === prev[i])) {
      return { cycle: true, period: len };
    }
  }
  return { cycle: false, period: 0 };
}
module.exports = { detectCycle };
